# Lemma variants recorded for the verb 'distribuire' (lila:lemmaVariant).
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?italianWord ?variantWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma lila:hasPOS lila:verb ;
        ontolex:writtenRep ?italianWord ;
        lila:lemmaVariant ?variantLemma .
    ?variantLemma ontolex:writtenRep ?variantWord .
  }
  FILTER(STR(?italianWord) = "distribuire")
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?hypolemmaWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
        ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
    FILTER(STR(?italianWord) = "manifestare")
    ?hypolemma lila:isHypolemma ?italianLemma ;
        ontolex:writtenRep ?hypolemmaWord .
  }
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?lemma ?italianWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma a ?lemmaType .
    FILTER(?lemmaType IN (lila:Lemma, lila:Hypolemma))
    ?lemma lila:hasPOS lila:noun .
    ?lemma ontolex:writtenRep ?italianWord .
    FILTER regex(str(?italianWord), "oria$")
  }
}
ORDER BY ?italianWord

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT (COUNT(*) AS ?count)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
    ?italianLemma lila:hasPOS lila:noun .
    ?italianLemma ontolex:writtenRep ?italianWord .
    FILTER(REGEX(STR(?italianWord), "^antr"))
  }
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT (COUNT(DISTINCT ?italianLemma) AS ?count)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord ;
                  lila:hasPOS lila:verb ;
                  lila:hasInflectionType lila:c3i .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }
}

PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?hyponymWr ?definition
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?fiumeWord ontolex:canonicalForm [ ontolex:writtenRep ?fiumeWr ] ;
                ontolex:sense ?fiumeSense .
    FILTER(STR(?fiumeWr) = "fiume")
    ?fiumeSense lexinfo:hypernym ?hyponymSense .
    ?hyponymWord ontolex:sense ?hyponymSense ;
                 ontolex:canonicalForm [ ontolex:writtenRep ?hyponymWr ] .
    OPTIONAL { ?hyponymSense skos:definition ?definition }
  }
}

PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?partWr ?definition
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?wholeWord ontolex:canonicalForm [ ontolex:writtenRep ?wholeWr ] ;
        ontolex:sense ?wholeSense .
    FILTER(STR(?wholeWr) = "paglia")
    ?partSense lexinfo:partMeronym ?wholeSense .
    ?partWord ontolex:sense ?partSense ;
        ontolex:canonicalForm [ ontolex:writtenRep ?partWr ] .
    OPTIONAL { ?partSense skos:definition ?definition }
  }
}

PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?italianWord
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?wr ] .
    FILTER(STR(?wr) = "popolato")
    ?word ontolex:sense ?sense .

    { ?sense lexinfo:antonym ?antonymSense . }
    UNION
    { ?antonymSense lexinfo:antonym ?sense . }

    ?antonymEntry ontolex:sense ?antonymSense .
  }

  ?antonymEntry ontolex:canonicalForm ?italianLemma .
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
