                 marl:hasPolarityValue ?polarityValue .

  ?translationEntry ontolex:canonicalForm ?italianLemma ;
                    vartrans:translatableAs ?parmigianoLexEntry .
  ?parmigianoLexEntry ontolex:canonicalForm ?parmigianoLemma .
  ?parmigianoLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> ;
                   ontolex:writtenRep ?parmigianoWord .
}
GROUP BY ?italianWord ?parmigianoWord

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?italianWord ?emotionLabel
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  lila:hasPOS lila:adjective ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  ?emotionEntry ontolex:canonicalForm ?italianLemma .

  GRAPH <http://w3id.org/elita> {
    ?emotionEntry elita:HasEmotion ?emotion .
    ?emotion rdfs:label ?emotionLabel .
  }

  FILTER(?emotion IN (elita:Amore, elita:Disgusto))
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?italianWord ?polarityValue
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord ;
                  lila:hasPOS ?pos .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
    FILTER(?pos IN (lila:noun, lila:adjective))
    FILTER(STRENDS(?italianWord, "-iuto"))
  }

  ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                 marl:hasPolarity marl:Negative ;
                 marl:hasPolarityValue ?polarityValue .
}

PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?resultWr
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?wr ] .
    FILTER(STR(?wr) = "capinera")
    ?word ontolex:sense ?sense .

    {
      ?sense lexinfo:hypernym ?resultSense .
      ?resultWord ontolex:sense ?resultSense ;
                  ontolex:canonicalForm [ ontolex:writtenRep ?resultWr ] .
    }
    UNION
    {
      ?resultSense lexinfo:partMeronym ?sense .
      ?resultWord ontolex:sense ?resultSense ;
                  ontolex:canonicalForm [ ontolex:writtenRep ?resultWr ] .
    }
  }
}

PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?italianWord
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?ciboWord ontolex:canonicalForm [ ontolex:writtenRep ?ciboWr ] ;
               ontolex:sense ?ciboSense .
    FILTER(STR(?ciboWr) = "cibo")

    # First level down: direct hyponyms of "cibo"
    ?ciboSense lexinfo:hypernym ?level1Sense .

    # Second level down: hyponyms of the first level
    ?level1Sense lexinfo:hypernym ?level2Sense .

    # Get the lexical entry for the second level
    ?level2Word ontolex:sense ?level2Sense .
  }

  # Link to LiITA to get the Italian lemma and its written form
  ?level2Word ontolex:canonicalForm ?italianLemma .
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }
}

