PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?otherItalianWord ?sicilianWord
WHERE {
  # Reference word: 'mandria'
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
    FILTER(STR(?italianWord) = "mandria")
  }
  ?italianLexEntry ontolex:canonicalForm ?italianLemma ;
                   vartrans:translatableAs ?sicilianLexEntry .
  ?sicilianLexEntry ontolex:canonicalForm ?sicilianLemma .
  ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
                 ontolex:writtenRep ?sicilianWord .

  # Other Italian words sharing the same Sicilian translation
  GRAPH <http://liita.it/data> {
    ?otherItalianLemma a ?otherLemmaType ;
                       ontolex:writtenRep ?otherItalianWord .
    FILTER(?otherLemmaType IN (lila:Lemma, lila:Hypolemma))
  }
  FILTER(?otherItalianLemma != ?italianLemma)
  ?otherItalianLexEntry ontolex:canonicalForm ?otherItalianLemma ;
                        vartrans:translatableAs ?otherSicilianLexEntry .
  ?otherSicilianLexEntry ontolex:canonicalForm ?otherSicilianLemma .
  ?otherSicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
                      ontolex:writtenRep ?otherSicilianWord .
  FILTER(STR(?otherSicilianWord) = STR(?sicilianWord))
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?italianWord ?parmigianoWord
WHERE {
  # Find 'crapulone' and its Parmigiano translation
  GRAPH <http://liita.it/data> {
    ?referenceLemma a ?referenceLemmaType ;
                    ontolex:writtenRep ?referenceWord .
    FILTER(?referenceLemmaType IN (lila:Lemma, lila:Hypolemma))
    FILTER(STR(?referenceWord) = "crapulone")
  }

  ?referenceEntry ontolex:canonicalForm ?referenceLemma ;
                  vartrans:translatableAs ?parmigianoLexEntry .

  ?parmigianoLexEntry ontolex:canonicalForm ?parmigianoLemma .
  ?parmigianoLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> ;
                    ontolex:writtenRep ?parmigianoWord .

  # Find other Italian words that share the same Parmigiano translation
  ?italianLexEntry ontolex:canonicalForm ?italianLemma ;
                   vartrans:translatableAs ?otherParmigianoLexEntry .

  ?otherParmigianoLexEntry ontolex:canonicalForm ?parmigianoLemma .

  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  FILTER(STR(?italianWord) != "crapulone")
}

PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?coHyponymWr ?hypernymWr
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?targetWord ontolex:canonicalForm [ ontolex:writtenRep ?targetWr ] ;
                ontolex:sense ?targetSense .
    FILTER(STR(?targetWr) = "novelliere")

    ?targetSense lexinfo:hyponym ?hypernymSense .
    ?hypernymWord ontolex:sense ?hypernymSense ;
                  ontolex:canonicalForm [ ontolex:writtenRep ?hypernymWr ] .

    ?coHyponymWord ontolex:sense ?coHyponymSense ;
                  ontolex:canonicalForm [ ontolex:writtenRep ?coHyponymWr ] .
    ?coHyponymSense lexinfo:hyponym ?hypernymSense .

    FILTER(?coHyponymWord != ?targetWord)
  }
}

PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?otherWr ?partWr
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?insalataWord ontolex:canonicalForm [ ontolex:writtenRep ?insalataWr ] ;
                  ontolex:sense ?insalataSense .
    FILTER(STR(?insalataWr) = "insalata")

    ?partSense lexinfo:partMeronym ?insalataSense .
    ?partWord ontolex:sense ?partSense ;
              ontolex:canonicalForm [ ontolex:writtenRep ?partWr ] .

    ?partSense lexinfo:partMeronym ?otherWholeSense .
    ?otherWord ontolex:sense ?otherWholeSense ;
               ontolex:canonicalForm [ ontolex:writtenRep ?otherWr ] .

    FILTER(STR(?otherWr) != "insalata")
  }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?otherSicilianLemma ?otherSicilianWord
WHERE {
  # Find the Sicilian lemma 'arrùmpiri'
  ?arrumpiriLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
                  ontolex:writtenRep ?arrumpiriWord .
  FILTER(STR(?arrumpiriWord) = "arrùmpiri")

  # Lexical entry for 'arrùmpiri'
  ?arrumpiriLexEntry ontolex:canonicalForm ?arrumpiriLemma .

  # Italian lemmas that translate to 'arrùmpiri' (Italian → Sicilian direction)
  ?italianLexEntry vartrans:translatableAs ?arrumpiriLexEntry ;
                   ontolex:canonicalForm ?italianLemma .
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  # Other Sicilian lemmas that also translate at least one of those Italian lemmas
  ?otherItalianLexEntry vartrans:translatableAs ?otherSicilianLexEntry ;
                        ontolex:canonicalForm ?italianLemma .
  ?otherSicilianLexEntry ontolex:canonicalForm ?otherSicilianLemma .
  ?otherSicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
                      ontolex:writtenRep ?otherSicilianWord .

  # Exclude 'arrùmpiri' itself
  FILTER(?otherSicilianLemma != ?arrumpiriLemma)
}

