    FILTER(STR(?parlareWr) = "parlare")

    ?waySense lexinfo:hyponym ?parlareSense .
    ?word ontolex:sense ?waySense ;
          ontolex:canonicalForm [ ontolex:writtenRep ?italianWord ] .
    ?waySense skos:definition ?definition .
