  ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
                ontolex:writtenRep ?sicilianWord .
  FILTER(REGEX(STR(?sicilianWord), "ina$"))
}
GROUP BY ?italianLemma ?sicilianLemma

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?italianWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  lila:hasPOS lila:verb ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  ?italianLexEntry ontolex:canonicalForm ?italianLemma ;
                   vartrans:translatableAs ?sicilianLexEntry .

  ?sicilianLexEntry ontolex:canonicalForm ?sicilianLemma .
  ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
                 ontolex:writtenRep ?sicilianWord .

  FILTER(STR(?italianWord) = STR(?sicilianWord))
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?italianWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord ;
                  lila:hasPOS lila:noun .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  ?polarityEntry1 ontolex:canonicalForm ?italianLemma ;
                  marl:hasPolarity ?polarity1 ;
                  marl:hasPolarityValue ?value1 .

  ?polarityEntry2 ontolex:canonicalForm ?italianLemma ;
                  marl:hasPolarity ?polarity2 ;
                  marl:hasPolarityValue ?value2 .

  FILTER(?value1 != ?value2)
  FILTER(ABS(xsd:float(?value1) - xsd:float(?value2)) > 0.25)
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT (AVG(?n) AS ?avgTranslations)
WHERE {
  {
    SELECT ?italianWord (COUNT(DISTINCT ?sicilianWord) AS ?n)
    WHERE {
      GRAPH <http://liita.it/data> {
        ?italianLemma a ?italianLemmaType ;
                      ontolex:writtenRep ?italianWord ;
                      lila:hasPOS lila:verb .
        FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
      }
      ?italianEntry ontolex:canonicalForm ?italianLemma ;
                    vartrans:translatableAs ?sicilianEntry .
      ?sicilianEntry ontolex:canonicalForm ?sicilianLemma .
      ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
                     ontolex:writtenRep ?sicilianWord .
    }
    GROUP BY ?italianWord
  }
}

PREFIX complit: <http://klab/lexicon/vocabulary/compl-it#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT (AVG(?count) AS ?average)
WHERE {
  {
    SELECT ?word (COUNT(DISTINCT ?sense) AS ?count)
    WHERE {
      SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
        ?word ontolex:sense ?targetSense .
        ?targetSense complit:hasSemanticType ?semanticType .
        FILTER(STRENDS(STR(?semanticType), "Cause_Change_Location"))
        ?word ontolex:sense ?sense .
      }
    }
    GROUP BY ?word
  }
}

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(?emotionCount) AS ?avgEmotionCount)
WHERE {
  {
    SELECT ?italianLemma (COUNT(DISTINCT ?emotion) AS ?emotionCount)
    WHERE {
      GRAPH <http://liita.it/data> {
        ?italianLemma a ?italianLemmaType .
        FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
      }

      ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                     marl:hasPolarity ?polarity ;
                     marl:hasPolarityValue ?polarityValue .
      FILTER(xsd:float(?polarityValue) > 0.8)

      ?emotionEntry ontolex:canonicalForm ?italianLemma .
      GRAPH <http://w3id.org/elita> {
        ?emotionEntry elita:HasEmotion ?emotion .
      }
    }
    GROUP BY ?italianLemma
    HAVING(COUNT(DISTINCT ?emotion) > 0)
  }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?emotionLabel ?count ?avgPolarityValue ?withSicilian
WHERE {
  {
    SELECT ?emotion ?emotionLabel (COUNT(DISTINCT ?italianLemma) AS ?count)
    WHERE {
      GRAPH <http://liita.it/data> {
        ?italianLemma a ?italianLemmaType .
        FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
      }
      ?emotionEntry ontolex:canonicalForm ?italianLemma .
      GRAPH <http://w3id.org/elita> {
        ?emotionEntry elita:HasEmotion ?emotion .
        ?emotion rdfs:label ?emotionLabel .
      }
    }
    GROUP BY ?emotion ?emotionLabel
  }
  OPTIONAL {
    SELECT ?emotion (AVG(xsd:float(?polarityValue)) AS ?avgPolarityValue)
    WHERE {
      GRAPH <http://liita.it/data> {
        ?italianLemma a ?italianLemmaType .
        FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
      }
      ?emotionEntry ontolex:canonicalForm ?italianLemma .
      GRAPH <http://w3id.org/elita> {
        ?emotionEntry elita:HasEmotion ?emotion .
      }
      ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                     marl:hasPolarity ?polarity ;
                     marl:hasPolarityValue ?polarityValue .
    }
    GROUP BY ?emotion
  }
  OPTIONAL {
    SELECT ?emotion (COUNT(DISTINCT ?italianLemma) AS ?withSicilian)
    WHERE {
      GRAPH <http://liita.it/data> {
        ?italianLemma a ?italianLemmaType .
        FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
      }
      ?emotionEntry ontolex:canonicalForm ?italianLemma .
      GRAPH <http://w3id.org/elita> {
        ?emotionEntry elita:HasEmotion ?emotion .
      }
      ?translationEntry ontolex:canonicalForm ?italianLemma ;
                        vartrans:translatableAs ?sicilianLexEntry .
      ?sicilianLexEntry ontolex:canonicalForm ?sicilianLemma .
      ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> .
    }
    GROUP BY ?emotion
  }
}
ORDER BY ?emotionLabel

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT ?pos
       (COUNT(DISTINCT ?italianLemma) AS ?count)
       (COUNT(DISTINCT ?italianLemmaWithSicilian) AS ?withSicilian)
       (COUNT(DISTINCT ?italianLemmaWithParmigiano) AS ?withParmigiano)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  lila:hasPOS ?pos .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  OPTIONAL {
    ?italianSicilianEntry ontolex:canonicalForm ?italianLemma ;
                         vartrans:translatableAs ?sicilianEntry .
    ?sicilianEntry ontolex:canonicalForm ?sicilianLemma .
    ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> .
    BIND(?italianLemma AS ?italianLemmaWithSicilian)
  }

  OPTIONAL {
    ?italianParmigianoEntry ontolex:canonicalForm ?italianLemma ;
                            vartrans:translatableAs ?parmigianoEntry .
    ?parmigianoEntry ontolex:canonicalForm ?parmigianoLemma .
    ?parmigianoLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> .
    BIND(?italianLemma AS ?italianLemmaWithParmigiano)
  }
}
GROUP BY ?pos
ORDER BY ?pos

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT ?polarity
       (COUNT(DISTINCT ?italianLemma) AS ?count)
       (COUNT(DISTINCT IF(BOUND(?emotionEntry), ?italianLemma, ?none)) AS ?withEmotion)
       (COUNT(DISTINCT IF(BOUND(?parmigianoLemma), ?italianLemma, ?none)) AS ?withParmigiano)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                 marl:hasPolarity ?polarity .

  OPTIONAL {
    ?emotionEntry ontolex:canonicalForm ?italianLemma .
    GRAPH <http://w3id.org/elita> {
      ?emotionEntry elita:HasEmotion ?emotion .
    }
  }

  OPTIONAL {
    ?translationEntry ontolex:canonicalForm ?italianLemma ;
                      vartrans:translatableAs ?parmigianoLexEntry .
    ?parmigianoLexEntry ontolex:canonicalForm ?parmigianoLemma .
    ?parmigianoLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> .
  }
}
GROUP BY ?polarity
ORDER BY ?polarity

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>

SELECT DISTINCT ?lemmaBank
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma a ?lemmaType ;
           dcterms:isPartOf ?lemmaBank .
    FILTER(?lemmaType IN (lila:Lemma, lila:Hypolemma))
  }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>

SELECT ?resource (COUNT(DISTINCT ?italianLemma) AS ?count)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  dcterms:isPartOf ?resource .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }
}
GROUP BY ?resource
ORDER BY DESC(?count)

PREFIX elita: <http://w3id.org/elita/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?emotion ?emotionLabel
WHERE {
  GRAPH <http://w3id.org/elita> {
    ?emotion rdf:type elita:Emotion ;
             rdfs:label ?emotionLabel .
  }
}
